public class Main {
    public static void main(String[] args) {
        Champ c = new Champ(20, 30);
        System.out.println("Surface : " + c.surface() + " m²");
        System.out.println("Clôture : " + c.cloture() + " m");
    }
}

class Champ {
    int largeur;
    int longueur;

    Champ(int largeur, int longueur) {
        this.largeur = largeur;
        this.longueur = longueur;
    }

    int surface() {
        return largeur * longueur;
    }

    int cloture() {
        return 2 * (largeur + longueur);
    }
}

