import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        Moto m = new Moto(sc.nextLine(), 0);
        String ligne = sc.nextLine();
        while (!ligne.equals("fin")) {
            m.rouler(Integer.parseInt(ligne));
            ligne = sc.nextLine();
        }
        System.out.println("Plaque : " + m.plaque);
        System.out.println("Kilomètres : " + m.kilometres);
        System.out.println("Vidange : " + m.vidange());
    }
}

class Moto {
    String plaque;
    int kilometres;

    Moto(String plaque, int kilometres) {
        this.plaque = plaque;
        this.kilometres = kilometres;
    }

    void rouler(int km) {
        kilometres += km;
    }

    boolean vidange() {
        return kilometres >= 5000;
    }
}
